{
  "vulnerable": true,
  "findings": [
    {
      "category": "C1",
      "title": "SOQL Injection",
      "severity": "Medium",
      "file": "TaskSearchController.cls",
      "lines": "findTasksBySubject",
      "explanation": "The method concatenates user input into a dynamic SOQL query string, which can lead to SOQL injection.",
      "remediation": "Use bind variables or Database.queryWithBinds to safely include user input in SOQL queries."
    },
    {
      "category": "C2",
      "title": "CRUD/FLS Violation",
      "severity": "Medium",
      "file": "TaskSearchController.cls",
      "lines": "findTasksBySubject",
      "explanation": "The method does not enforce field-level security (FLS) for the Task object fields.",
      "remediation": "Use Security.stripInaccessible to enforce FLS on the query results."
    }
  ]
}

